SELECT 
  FROM biz55_erp_fee_charge
       INNER JOIN ast06_tr          ON ast06_tr_id      = biz55_tr_id
       INNER JOIN act02_journal     ON act02_tr_id      = biz55_tr_id
       INNER JOIN act03_journal_dtl ON act03_journal_id = act02_journal_id
 WHERE biz55_charge_date = #{chargeDate}
   AND ast06_tr_cd       = #{trCode}
   AND ast06_company_id  = #{companyId}
 ORDER BY act02_date, act02_journal_id, act03_seq

SELECT 
  FROM act02_journal
       INNER JOIN act03_journal_dtl ON act03_journal_id = act02_journal_id
 WHERE act02_journal_id = #{journalId}
   AND act02_company_id = #{companyId}
 ORDER BY act03_seq

